import{_ as a,o as d,c as e,a2 as i}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"评估体系","description":"Hearth 的评估金字塔、任务集、核心指标、验证器、轨迹重放、故障注入、安全红队与阶段门槛。","frontmatter":{"title":"评估体系","description":"Hearth 的评估金字塔、任务集、核心指标、验证器、轨迹重放、故障注入、安全红队与阶段门槛。","outline":[2,3]},"headers":[],"relativePath":"architecture/evaluation.md","filePath":"architecture/evaluation.md","lastUpdated":1793706118000}'),l={name:"architecture/evaluation.md"};function r(o,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[i('<p class="eyebrow">EVALUATION</p><h1 id="评估体系" tabindex="-1">评估体系 <a class="header-anchor" href="#评估体系" aria-label="Permalink to &quot;评估体系&quot;">​</a></h1><p class="lead">Demo 不是能力。评估体系用任务集、指标、基线、验证器、轨迹重放、故障注入和统计纪律证明系统真的能做。</p><h2 id="评估体系-1" tabindex="-1">评估体系 <a class="header-anchor" href="#评估体系-1" aria-label="Permalink to &quot;评估体系&quot;">​</a></h2><p>Demo 不是能力。Hearth 只相信可重复、可验证、带失败样本的证据。</p><h3 id="评估金字塔" tabindex="-1">评估金字塔 <a class="header-anchor" href="#评估金字塔" aria-label="Permalink to &quot;评估金字塔&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>评什么</th><th>频率</th></tr></thead><tbody><tr><td>Unit/Tool</td><td>解析器、连接器、策略、验证器</td><td>每次提交</td></tr><tr><td>Task-level</td><td>单任务端到端成功</td><td>每次发布</td></tr><tr><td>Trajectory Replay</td><td>历史轨迹重放、换路由和失败恢复</td><td>持续</td></tr><tr><td>Shadow</td><td>真实输入、无外部副作用</td><td>持续</td></tr><tr><td>Live Pilot</td><td>真实用户、真实副作用、受控范围</td><td>阶段推进前</td></tr><tr><td>Long-run</td><td>多设备驻留、设备切换、记忆演化</td><td>阶段验收</td></tr></tbody></table><h3 id="任务集" tabindex="-1">任务集 <a class="header-anchor" href="#任务集" aria-label="Permalink to &quot;任务集&quot;">​</a></h3><p>初始建立 40–60 个真实任务，覆盖八类任务族：邮件、日历、文档、调研、代码、网页、桌面、跨应用流程。</p><p>要求：</p><ul><li>每条任务有明确输入、验收标准和验证器；</li><li>包含正常、边界、失败和恶意输入；</li><li>真实脱敏数据优先，合成数据单独标记；</li><li>保留 holdout 集，不能反复调参；</li><li>失败样本不能被删除；</li><li>新增能力时增加对应任务，而不是只增加 demo；</li><li>MVP 的窄任务族也必须有独立任务集，不能只靠一条演示脚本。</li></ul><h3 id="核心指标" tabindex="-1">核心指标 <a class="header-anchor" href="#核心指标" aria-label="Permalink to &quot;核心指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>定义</th><th>初始目标</th></tr></thead><tbody><tr><td>Verified Task Success</td><td>通过验证器的任务比例</td><td>Stage 1 ≥ 70%</td></tr><tr><td>Human Minutes / Verified Task</td><td>每有效完成的人工分钟</td><td>相对基线下降 ≥ 30%</td></tr><tr><td>Interruptions / Verified Task</td><td>每任务打断次数</td><td>≤ 1.0</td></tr><tr><td>Recovery Rate</td><td>崩溃/断网/重启后恢复比例</td><td>≥ 95%</td></tr><tr><td>Duplicate Side Effects</td><td>故障注入下重复副作用</td><td>0 / 200</td></tr><tr><td>Unsafe Action Rate</td><td>未授权高风险动作</td><td>0</td></tr><tr><td>Token / Verified Success</td><td>每有效完成 Token</td><td>持续下降</td></tr><tr><td>Cost / Verified Success</td><td>每有效完成综合成本</td><td>可解释且可控</td></tr><tr><td>Memory Precision</td><td>召回记忆确实相关且正确</td><td>≥ 90%</td></tr><tr><td>Skill Regression</td><td>晋升技能导致旧任务退化</td><td>0 严重回归</td></tr></tbody></table><p>目标值是早期工程门槛，不是营销承诺，必须用真实数据更新。</p><h3 id="基线比较" tabindex="-1">基线比较 <a class="header-anchor" href="#基线比较" aria-label="Permalink to &quot;基线比较&quot;">​</a></h3><p>至少比较：</p><ol><li>全人工；</li><li>直接使用 Codex；</li><li>Hearth 的当前版本；</li><li>Hearth 的替代路由或技能版本。</li></ol><p>比较成功率、人工分钟、打断、Token、延迟、成本和失败恢复，而不是只比较输出文本。</p><h3 id="验证器" tabindex="-1">验证器 <a class="header-anchor" href="#验证器" aria-label="Permalink to &quot;验证器&quot;">​</a></h3><ul><li>代码：测试、类型检查、diff、CI；</li><li>文档：结构、引用、格式、用户验收；</li><li>邮件：收件人、事实、语气、发送审批、Receipt；</li><li>网页：DOM/可访问性状态、截图、最终状态；</li><li>桌面：可访问性树、截图、目标状态；</li><li>研究：来源和引用；</li><li>数据：schema、行数、抽样、对账、复现脚本；</li><li>副作用：幂等键、Receipt、对账。</li></ul><h3 id="轨迹重放与故障注入" tabindex="-1">轨迹重放与故障注入 <a class="header-anchor" href="#轨迹重放与故障注入" aria-label="Permalink to &quot;轨迹重放与故障注入&quot;">​</a></h3><p>历史轨迹应能重放、换路由、替换模型/执行器并比较结果。故障注入至少覆盖：进程崩溃、网络中断、超时、重复投递、磁盘满、provider 限流/认证过期、设备离线、外部结果不确定、审批过期、记忆/缓存失效。</p><h3 id="安全与红队评估" tabindex="-1">安全与红队评估 <a class="header-anchor" href="#安全与红队评估" aria-label="Permalink to &quot;安全与红队评估&quot;">​</a></h3><p>红队必须尝试让系统越权、泄露秘密、重复副作用、绕过审批、污染记忆、扩大技能权限和利用设备。评估结果要进入发布门槛，而不是放在附录。</p><h3 id="统计与评估纪律" tabindex="-1">统计与评估纪律 <a class="header-anchor" href="#统计与评估纪律" aria-label="Permalink to &quot;统计与评估纪律&quot;">​</a></h3><ul><li>预先定义指标和样本；</li><li>不用平均值掩盖某个任务族崩溃；</li><li>保留失败和拒绝样本；</li><li>评估集不能用于技能训练；</li><li>区分统计显著和产品有意义；</li><li>记录模型、执行器、提示、工具和版本；</li><li>变更后重新跑基线，避免“只跟旧版本比”。</li></ul><h3 id="阶段发布门槛" tabindex="-1">阶段发布门槛 <a class="header-anchor" href="#阶段发布门槛" aria-label="Permalink to &quot;阶段发布门槛&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>必须证明</th></tr></thead><tbody><tr><td>Stage 0</td><td>可点击端到端原型、12 个可验收任务、核心协议和威胁模型</td></tr><tr><td>Stage 1</td><td>MVP 可在浏览器每天使用；可恢复、可审批、无重复副作用、Codex 任务可验收</td></tr><tr><td>Stage 2</td><td>邮件/日历/文档/网页真实任务可完成，Token 可控</td></tr><tr><td>Stage 3</td><td>GUI 可接管，失败可恢复，无越权</td></tr><tr><td>Stage 4</td><td>主动任务不造成通知疲劳，审批和安全可审计</td></tr><tr><td>Stage 5</td><td>记忆可纠正/遗忘，技能可评估/回滚</td></tr><tr><td>Stage 6</td><td>多设备一致、离线恢复、迁移和撤销可靠</td></tr></tbody></table><h3 id="评估反模式" tabindex="-1">评估反模式 <a class="header-anchor" href="#评估反模式" aria-label="Permalink to &quot;评估反模式&quot;">​</a></h3><ul><li>只看 demo 和截图；</li><li>只测成功路径；</li><li>只统计模型输出，不验证副作用；</li><li>用合成任务代替真实任务；</li><li>把 Token 降低当成唯一目标；</li><li>评估集被技能训练污染；</li><li>失败样本被删除；</li><li>用平均值掩盖某个任务族崩溃；</li><li>自评通过；</li><li>没有安全回归测试；</li><li>用“以后补评估”推进阶段。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>安全与评估不是 Stage 6 的收尾工作。Stage 0 就要有威胁模型和任务集，Stage 1 就要有 MVP 的真实任务验收、恢复和副作用演练；后续每扩一个执行器，安全与评测面同步扩大。</p>',32)])])}const p=a(l,[["render",r]]);export{b as __pageData,p as default};
